-- ============================================================================
-- 0004b_onet_dna_data.sql
--
-- Skor Career DNA untuk 555 okupasi. Dibuat oleh supabase/dna/derive_dna.py
-- dari O*NET 30.3 -- jangan diedit tangan; ubah supabase/dna/dna_map.py lalu
-- generate ulang.
--
-- Formatnya sengaja ringkas. Versi baris-per-atribut butuh 28.044 INSERT (1,5 MB)
-- dan tidak muat di SQL Editor Supabase. Di sini tiap okupasi jadi SATU baris
-- berisi dua array sepanjang 54, lalu dibongkar server-side. Hasil akhirnya di
-- tabel `onet_dna` persis sama, tapi filenya cukup kecil untuk ditempel di
-- browser.
-- ============================================================================

begin;

create temporary table _dna_in (
  soc_code text primary key,
  scores   numeric[],
  ranks    smallint[]
) on commit drop;

-- Urutan 54 atribut. Array di bawah mengikuti urutan ini persis.
create temporary table _dna_order (pos int primary key, attribute_code text) on commit drop;

-- Okupasi yang mewarisi sebagian layer dari profesi terkait (belum disurvei O*NET)
create temporary table _dna_inherit (soc_code text, layer_code text, from_soc text) on commit drop;

;

-- Bongkar jadi baris per atribut. `is_dominant` dihitung dari peringkat versus
-- jumlah pilihan layer-nya, bukan disimpan dua kali.
select i.soc_code,
       o.attribute_code,
       i.scores[o.pos],
       i.ranks[o.pos],
       i.ranks[o.pos] <= l.selection_count,
       case
         -- Warisan diperiksa lebih dulu: kalau layer-nya diwarisi, nilai
         -- ENV_REMOTE/ENV_HYBRID juga datang dari profesi asal, bukan dihitung
         -- ulang di sini.
         when inh.from_soc is not null then 'inherited:' || inh.from_soc
         when o.attribute_code in ('ENV_REMOTE','ENV_HYBRID') then 'rule'
         else 'onet'
       end
from _dna_in i
cross join _dna_order o
join public.dna_attributes a on a.code = o.attribute_code
join public.dna_layers     l on l.code = a.layer_code
left join _dna_inherit inh on inh.soc_code = i.soc_code and inh.layer_code = a.layer_code
where i.scores[o.pos] is not null
on conflict (soc_code, attribute_code) do update set
  score = excluded.score, rank_in_layer = excluded.rank_in_layer,
  is_dominant = excluded.is_dominant, dna_source = excluded.dna_source;

commit;
